"""Probe-only camera-relative optical source IDs. No Kit/pxr/OVRTX imports.
16 emissive moving cells per camera: 12 row bits, 2 role bits, white/black anchors.
Bit value is cell row (upper=1, lower=0), not a metadata label or postrender paint.
Boards alter the scene; a passing board proves source phase, not all-body coverage.
"""
import numpy as np


def paths(role):
    return [f'/LiveWitness/r{role}_board'] + [f'/LiveWitness/r{role}_bit{i}' for i in range(16)]


def usd():
    materials = []
    for name, value in [('White', 5), ('Black', 0)]:
        materials.append(f'''def Material "{name}" {{
 token outputs:surface.connect = </LiveWitness/{name}/Shader.outputs:surface>
 def Shader "Shader" {{
  uniform token info:id = "UsdPreviewSurface"
  color3f inputs:diffuseColor = (0, 0, 0)
  color3f inputs:emissiveColor = ({value}, {value}, {value})
  float inputs:roughness = 1
  token outputs:surface
 }}
}}''')
    objects = []
    for role in range(3):
        for i, path in enumerate(paths(role)):
            material = 'Black' if i == 0 else 'White'
            objects.append(f'''def Cube "{path.rsplit('/',1)[1]}" (prepend apiSchemas = ["MaterialBindingAPI"]) {{
 double size = 1
 rel material:binding = </LiveWitness/{material}>
}}''')
    return 'def Scope "LiveWitness" {\n' + '\n'.join(materials + objects) + '\n}\n'


def matrices(camera_world, intrinsics, source_index, role, width=960, height=600):
    if not 0 <= source_index < 4096 or not 0 <= role < 3:
        raise ValueError('Witness supports source rows0..4095 and roles0..2')
    focal, aperture_x, aperture_y = intrinsics
    fx, fy = width * focal / aperture_x, height * focal / aperture_y
    bits = [(source_index >> i) & 1 for i in range(12)] + [role & 1, (role >> 1) & 1, 1, 0]
    pixel_specs = [(width/2, height/2, 342, 72, .061)]
    pixel_specs += [(width/2 - 150 + 20*i, height/2 + (-20 if bit else 20), 12, 12, .06)
                    for i, bit in enumerate(bits)]
    result = []
    for x, y, sx, sy, z in pixel_specs:
        matrix = np.diag([sx*z/fx, sy*z/fy, .00015, 1.0])
        matrix[3, :3] = [(x-width/2)*z/fx, -(y-height/2)*z/fy, -z]
        result.append(matrix @ camera_world)
    return np.asarray(result)


def decode(image):
    height, width = image.shape[:2]
    values = []
    for i in range(16):
        x = int(width/2 - 150 + 20*i)
        lum = []
        for y in [int(height/2 - 20), int(height/2 + 20)]:
            lum.append(float(np.median(image[y-1:y+2, x-1:x+2, :3])))
        values.append(lum[0]-lum[1])
    bits = [int(v > 0) for v in values]
    row = sum(b << i for i, b in enumerate(bits[:12]))
    role = bits[12] + 2*bits[13]
    return dict(row=row, role=role, min_contrast=min(abs(v) for v in values),
                anchors_ok=bits[14:] == [1, 0], cell_contrasts=values,
                confident=min(abs(v) for v in values) >= 30 and bits[14:] == [1, 0])

"""Opt-in, source-guarded PIPER physics probes. Importing runs no Isaac code.

Load with importlib.util.spec_from_file_location, then install(env, variant=...).
Valid variants: baseline, implicit-once, lazy-acceleration, implicit-lazy.
Call handle.restore() before disposing env. No SDK file is modified.
NOT a qualified recorder; all outputs must carry dataset_admissible=False.
"""
from __future__ import annotations

import hashlib
import json
from pathlib import Path

MANIFEST = Path('/tmp/live30-deep-physics.preimages.json')


def verify_preimages():
    expected = json.loads(MANIFEST.read_text())
    for name, digest in expected['sha256'].items():
        actual = hashlib.sha256(Path(name).read_bytes()).hexdigest()
        if actual != digest:
            raise RuntimeError(f'Probe preimage changed: {name}: {actual} != {digest}')
    return expected


class Handle:
    def __init__(self, env, variant):
        self.env, self.variant = env, variant
        self.saved = []
        self.active = False
        self.counts = {}
        self.stats = dict(groups=0, full_writes=0, cached_submits=0, lazy_updates=0)
        self.restored = False

    def patch(self, obj, name, value):
        self.saved.append((obj, name, name in vars(obj), vars(obj).get(name)))
        setattr(obj, name, value)

    def restore(self):
        if self.active:
            raise RuntimeError('Cannot restore inside an active physics group')
        if self.restored:
            return
        for obj, name, owned, old in reversed(self.saved):
            if owned:
                setattr(obj, name, old)
            else:
                delattr(obj, name)
        self.restored = True

    def receipt(self):
        return dict(variant=self.variant, dataset_admissible=False,
                    physics_dt_unchanged=True, per_substep_submit_preserved=True,
                    acceleration_semantics=('read-interval finite difference' if 'lazy' in self.variant
                                            else 'unchanged'),
                    effort_telemetry_semantics=('computed once/control' if 'implicit' in self.variant
                                               else 'unchanged'),
                    **self.stats)


def _guard(robot):
    collection = robot.actuators
    if collection._control.native_actuator_path_active:
        raise RuntimeError('Native/Newton actuators forbidden for implicit probe')
    if collection._execution_actuators or collection._implicit_executor is None:
        raise RuntimeError('Requires exclusively exact upstream plain implicit actuators')
    if len(collection._implicit_executor.group_names) != len(collection):
        raise RuntimeError('Not all groups belong to implicit executor')
    if robot._instantaneous_wrench_composer.active or robot._permanent_wrench_composer.active:
        raise RuntimeError('External wrenches forbidden for implicit probe')
    if robot._fixed_tendon_target_dirty:
        raise RuntimeError('Dirty tendon command forbidden for implicit probe')


def install(env, *, variant='baseline'):
    if variant not in {'baseline', 'implicit-once', 'lazy-acceleration', 'implicit-lazy'}:
        raise ValueError(variant)
    verify_preimages()
    if len(env.robots) != 2 or env.render_substeps != 4:
        raise RuntimeError('Probe requires two PIPERs and FFFT')
    if abs(float(env.sim.cfg.dt) - 1.0 / 120.0) > 1e-12:
        raise RuntimeError('Probe requires unchanged 120 Hz physics')
    if not env.vr_runtime._validation_complete:
        raise RuntimeError('Install after canonical reset and native scene validation')
    handle = Handle(env, variant)
    implicit = 'implicit' in variant
    lazy = 'lazy' in variant
    original_advance = env._advance
    try:
        for robot in env.robots:
            if implicit:
                _guard(robot)
                original_write = robot.write_data_to_sim

                def write(_robot=robot, _original=original_write):
                    if not handle.active:
                        return _original()
                    _guard(_robot)
                    index = handle.counts[id(_robot)]
                    if index == 0:
                        _original()
                        handle.stats['full_writes'] += 1
                    else:
                        _robot.actuators.submit_commands()
                        handle.stats['cached_submits'] += 1
                    handle.counts[id(_robot)] += 1

                handle.patch(robot, 'write_data_to_sim', write)
                command = robot.actuators.target_command
                # Intercept the public target API. Direct mutation of command tensor buffers
                # remains prohibited by the probe contract and cannot be detected cheaply.
                for name in ('set_position_index', 'set_velocity_index', 'set_effort_index',
                             'set_position_mask', 'set_velocity_mask', 'set_effort_mask'):
                    original_set = getattr(command, name)

                    def setter(*args, _original=original_set, **kwargs):
                        if handle.active:
                            raise RuntimeError('Target mutation inside cached control group')
                        return _original(*args, **kwargs)

                    handle.patch(command, name, setter)
            if lazy:
                data = robot.data
                original_update = data.update

                def update(dt, _data=data, _original=original_update):
                    if not handle.active:
                        return _original(dt)
                    # Exact upstream update() except eager joint_acc access. The property
                    # remains available and on access differences over its elapsed interval.
                    _data._sim_timestamp += dt
                    if _data._fk_timestamp >= 0.0:
                        _data._fk_timestamp = _data._sim_timestamp
                    handle.stats['lazy_updates'] += 1

                handle.patch(data, 'update', update)

        def advance(repeat):
            if handle.active:
                raise RuntimeError('Nested _advance not supported')
            # Settling/reset/one-off forward remain fully canonical.
            if repeat != 4 or env._render_substep != 0 or not env.vr_runtime._validation_complete:
                return original_advance(repeat)
            handle.active = True
            handle.counts = {id(robot): 0 for robot in env.robots}
            before = env.sim.get_physics_step_count()
            try:
                result = original_advance(repeat)
                if env.sim.get_physics_step_count() - before != 4:
                    raise RuntimeError('Native physics count no longer four/control')
                if implicit and any(n != 4 for n in handle.counts.values()):
                    raise RuntimeError('Unexpected articulation write cadence')
                handle.stats['groups'] += 1
                return result
            finally:
                handle.active = False

        handle.patch(env, '_advance', advance)
    except BaseException:
        handle.restore()
        raise
    return handle

"""6.1 diagnostic only: three existing camera prims, native atlas vs separate RPs.

Import is CPU-only; instantiate AFTER SimulationApp. Run in a fresh diagnostic
scene with camera prims only, not simultaneously with the three old Camera RPs.
Call capture() after the existing app/control pump; never pump from this helper.
Returned GPU buffer is owned until release(); no raw pixels are staged to host.
Sequence counts fetches, not renderer source frames. Decode moving witnesses and
bind observed source phase to state/action history before claiming fresh RGB.
"""
from pathlib import Path
import hashlib
import math
import time

ROLES = ("left_wrist", "right_wrist", "scene")
AUDITED = {
    "isaacsim.sensors.experimental.rtx/isaacsim/sensors/experimental/rtx/impl/tiled_camera_sensor.py":
        "4d5d09a90d440f2154dad66f26ec3868318712b0a5f9703c762406205b5482a9",
    "isaacsim.core.experimental.objects/isaacsim/core/experimental/objects/impl/camera.py": "c96acc6a794a3b9dfaaaaa76d4975130b3b5dfeed6f4259302fca97ce5bfaa0c",
}


def source_guard(extension_root):
    receipts = []
    for relative, expected in AUDITED.items():
        path = Path(extension_root) / relative
        digest = hashlib.sha256(path.read_bytes()).hexdigest()
        if expected is not None and digest != expected:
            raise RuntimeError(f"Audited source changed: {path}")
        receipts.append(dict(path=str(path), sha256=digest, expected=expected))
    return receipts


def camera_signature(stage, paths):
    from pxr import UsdGeom
    signatures = {}
    for path in paths:
        prim = stage.GetPrimAtPath(path)
        if not prim.IsA(UsdGeom.Camera):
            raise ValueError(f"Existing Camera required: {path}")
        values = {str(attr.GetName()): str(attr.Get()) for attr in prim.GetAttributes()
                  if not str(attr.GetName()).startswith("_replicator:")}
        values["schemas"] = list(prim.GetAppliedSchemas())
        values["parent"] = str(prim.GetParent().GetPath())
        values["local_matrix"] = str(UsdGeom.Xformable(prim).GetLocalTransformation())
        signatures[path] = values
    return signatures


class CudaSubview:
    """PyNvVideoCodec 2.2.3 sample protocol; pitch acceptance needs GPU testing.

    cuda() returns an object with __cuda_array_interface__, not a dict. The
    allocation owner must survive encoder input consumption; no CPU copy here.
    """
    def __init__(self, owner, ptr, width, height, pitch):
        self.owner = owner
        self.__cuda_array_interface__ = dict(shape=(height, width, 4),
            strides=(pitch, 4, 1), data=(int(ptr), False), typestr="|u1", version=3)

    def cuda(self):
        return self


class ThreeCameraProbe:
    """Thin probe over upstream camera/Replicator APIs, with owned GPU outputs.

    mode: sensor -> public TiledCameraSensor.get_data(tiled=True,out=...).
          tiled -> direct rep.create.render_product_tiled; no optics editing.
          separate -> three stock products as comparison.
    payload: rgba -> owned CUDA arrays; h264 -> stock compressed packet bytes.
    H264 atlas is ONE 1920x1200 stream; crop into roles after decode. It is not
    three encoder sessions and must be measured independently from three RPs.
    """
    def __init__(self, camera_paths, *, mode="sensor", payload="rgba", width=960,
                 height=600, extension_root=None, reject_existing_products=True):
        import numpy as np
        import omni.replicator.core as rep
        import omni.usd
        from pxr import Sdf, Usd, UsdGeom, UsdRender
        if tuple(camera_paths) != ROLES or len(set(camera_paths.values())) != 3:
            raise ValueError("Ordered, unique left_wrist/right_wrist/scene paths required")
        if mode not in ("sensor", "tiled", "separate") or payload not in ("rgba", "h264"):
            raise ValueError("Unknown mode/payload")
        self.paths, self.mode, self.payload = dict(camera_paths), mode, payload
        self.width, self.height = int(width), int(height)
        self.sequence, self.busy, self.closed = 0, False, False
        self.buffers, self.products, self.annotators, self.handles = {}, [], [], []
        self.sensor = None
        self.completions, self.subscriptions = {}, []
        self.stage = omni.usd.get_context().get_stage()
        paths = list(self.paths.values())
        self.before = camera_signature(self.stage, paths)
        original_attrs = {p: {str(a.GetName()): a.Get() for a in self.stage.GetPrimAtPath(p).GetAttributes()} for p in paths}
        self.sources = source_guard(extension_root or "/data/vla-infrastructure/isaac61_production/env/lib/python3.12/site-packages/isaacsim/exts")
        if reject_existing_products:
            for prim in self.stage.Traverse():
                if prim.IsA(UsdRender.Product) and set(map(str, prim.GetRelationship("camera").GetTargets())) & set(paths):
                    raise RuntimeError(f"Old camera RP would contaminate comparison: {prim.GetPath()}")
        with Usd.EditContext(self.stage, self.stage.GetSessionLayer()):
            if mode == "sensor":
                from isaacsim.core.experimental.objects import Camera
                from isaacsim.sensors.experimental.rtx import TiledCameraSensor
                for path in paths:
                    camera = UsdGeom.Camera(self.stage.GetPrimAtPath(path))
                    ha, va = camera.GetHorizontalApertureAttr().Get(), camera.GetVerticalApertureAttr().Get()
                    if not np.isclose(va, ha * self.height / self.width, rtol=1e-5, atol=1e-7):
                        raise RuntimeError(f"Native sensor would change vertical aperture at {path}; use mode=tiled")
                wrapped = Camera(paths, reset_xform_op_properties=False)
                self.sensor = TiledCameraSensor(wrapped, resolution=(self.height, self.width),
                    annotators=["rgba"] if payload == "rgba" else [])
                self.products = [str(self.sensor.render_product.GetPath())]
            elif mode == "tiled":
                product = rep.create.render_product_tiled(paths, (self.width, self.height),
                    name="Live30DiagnosticAtlas")
                self.products, self.handles = [product.path], [product]
            else:
                self.handles = [rep.create.render_product(path, (self.width, self.height),
                    name=f"Live30Diagnostic_{role}") for role, path in self.paths.items()]
                self.products = [product.path for product in self.handles]
        # Stock RP creation authors exposure defaults on camera0. Restore source
        # camera opinions explicitly; this is a probe-only session-layer change.
        with Usd.EditContext(self.stage, self.stage.GetSessionLayer()):
            for path in paths:
                prim = self.stage.GetPrimAtPath(path)
                prim.SetMetadata("apiSchemas", Sdf.TokenListOp.CreateExplicit(self.before[path]["schemas"]))
                for attribute in list(prim.GetAttributes()):
                    name = str(attribute.GetName())
                    if name not in original_attrs[path]:
                        prim.RemoveProperty(name)
                    elif attribute.Get() != original_attrs[path][name]:
                        if original_attrs[path][name] is None:
                            attribute.Clear()
                        else:
                            attribute.Set(original_attrs[path][name])
        self.after = camera_signature(self.stage, paths)
        if self.before != self.after:
            self.close()
            changes = {p: {k: [self.before[p].get(k), self.after[p].get(k)] for k in set(self.before[p]) | set(self.after[p]) if self.before[p].get(k) != self.after[p].get(k)} for p in paths}
            raise RuntimeError(f"Constructing the probe changed camera optics/transform/schema: {changes}")
        self.order = []
        for path in self.products:
            prim = self.stage.GetPrimAtPath(path)
            targets = list(map(str, prim.GetRelationship("camera").GetTargets()))
            self.order.extend(targets)
        if set(self.order) != set(paths) or len(self.order) != 3:
            self.close()
            raise RuntimeError(f"Render-product camera routing wrong: {self.order}")
        self.role_indices = {role: self.order.index(path) for role, path in self.paths.items()}
        columns = math.ceil(math.sqrt(3))
        self.atlas_shape = (2*self.height, columns*self.width, 4)
        if payload == "h264" or mode != "sensor":
            for product in self.products:
                annotator = rep.AnnotatorRegistry.get_annotator(
                    "LdrColor" if payload == "h264" else "rgb",
                    device="cpu" if payload == "h264" else "cuda",
                    init_params={"compression": "h264"} if payload == "h264" else {})
                annotator.attach(product)
                self.annotators.append(annotator)
        self._observe_completions()
        self.manifest = dict(mode=mode, payload=payload, camera_paths=self.paths,
            observed_camera_order=self.order, role_indices=self.role_indices,
            sensor_resolution_hw=[self.height, self.width], atlas_shape_hwc=self.atlas_shape,
            padding_tiles=1 if mode != "separate" else 0, render_products=self.products,
            camera_signatures=self.before, source_receipts=self.sources,
            raw_host_staging=False, source_frame_identity_proven=False)

    def _observe_completions(self):
        import carb.eventdispatcher
        import omni.hydratexture
        handles = [self.sensor._hydra_texture] if self.sensor else self.handles
        for product in handles:
            texture = getattr(product, "hydra_texture", None)
            if texture is None or not hasattr(texture, "get_frame_info"):
                continue
            def done(event, texture=texture, path=product.path):
                result = event.payload.get("result_handle")
                if result is not None:
                    value = texture.get_frame_info(result)
                    self.completions[path] = dict(
                        host_monotonic_ns=time.monotonic_ns(),
                        frame_number=value.get("frame_number"),
                        device_mask=value.get("device_mask"),
                        subframe_count=value.get("subframe_count"),
                        pixel_binding_proven=False)
            subscription = carb.eventdispatcher.get_eventdispatcher().observe_event(
                observer_name=f"Live30Atlas:{id(self)}:{product.path}",
                event_name=omni.hydratexture.GLOBAL_EVENT_DRAWABLE_CHANGED,
                filter=texture.get_event_key(), on_event=done)
            self.subscriptions.append(subscription)

    def capture(self, *, producer_metadata=None):
        import warp as wp
        if self.closed or self.busy:
            raise RuntimeError("Closed probe or previous GPU frame not released")
        started = time.perf_counter_ns()
        arrays, info = {}, {}
        if self.payload == "h264":
            import numpy as np
            for index, annotator in enumerate(self.annotators):
                value = annotator.get_data(do_array_copy=True)
                if isinstance(value, dict):
                    info[str(index)] = value.get("info", {})
                    value = value.get("data")
                if value is None or not isinstance(value, np.ndarray) or not value.size:
                    return None
                if value.dtype != np.uint8 or value.ndim != 1:
                    raise RuntimeError("Expected flat compressed uint8 bytes")
                arrays[str(index)] = value.tobytes()
        else:
            if self.mode == "sensor":
                # Warm-up obtains native device/shape; subsequent fetches reuse out.
                value, metadata = self.sensor.get_data("rgba", tiled=True, out=self.buffers.get("atlas"))
                if value is None:
                    return None
                info["atlas"] = metadata
                if "atlas" not in self.buffers:
                    self._check_array(value, self.atlas_shape)
                    self.buffers["atlas"] = wp.empty_like(value)
                    wp.copy(self.buffers["atlas"], value)
                arrays["atlas"] = self.buffers["atlas"]
            else:
                for index, annotator in enumerate(self.annotators):
                    value = annotator.get_data(device="cuda", do_array_copy=False)
                    if isinstance(value, dict):
                        info[str(index)] = value.get("info", {})
                        value = value.get("data")
                    if value is None or getattr(value, "size", 0) == 0:
                        return None
                    shape = (self.height, self.width, 4) if self.mode == "separate" else self.atlas_shape
                    self._check_array(value, shape)
                    value = value.reshape(shape)
                    key = str(index)
                    if key not in self.buffers:
                        self.buffers[key] = wp.empty_like(value)
                    wp.copy(self.buffers[key], value)
                    arrays[key] = self.buffers[key]
            for device in {array.device for array in arrays.values()}:
                wp.synchronize_device(device)  # conservative copy-completion baseline
        self.sequence += 1
        self.busy = True
        return dict(fetch_sequence=self.sequence, host_monotonic_ns=time.monotonic_ns(),
            fetch_ns=time.perf_counter_ns()-started, arrays=arrays, annotator_info=info,
            producer_metadata=producer_metadata, render_completions=dict(self.completions),
            source_frame_identity_proven=False)

    @staticmethod
    def _check_array(value, shape):
        import warp as wp
        if not isinstance(value, wp.array) or not value.device.is_cuda or value.dtype != wp.uint8:
            raise RuntimeError("Expected native CUDA uint8 Warp output; no host promotion accepted")
        if value.size != math.prod(shape):
            raise RuntimeError(f"Output shape/size differs from configured atlas: {value.shape}")

    def cuda_views(self, capture):
        if self.payload != "rgba" or not self.busy or capture["fetch_sequence"] != self.sequence:
            raise RuntimeError("Current owned raw GPU capture required")
        views = {}
        for role, index in self.role_indices.items():
            if self.mode == "separate":
                array = capture["arrays"][str(index)]
                offset, pitch = 0, self.width*4
            else:
                array = next(iter(capture["arrays"].values()))
                pitch = self.atlas_shape[1]*4
                offset = (index//2)*self.height*pitch + (index%2)*self.width*4
            views[role] = CudaSubview(array, array.ptr+offset, self.width, self.height, pitch)
        return views

    def release(self, capture):
        if not self.busy or capture["fetch_sequence"] != self.sequence:
            raise RuntimeError("Stale/double release")
        self.busy = False

    def close(self):
        if self.closed:
            return
        self.subscriptions.clear()
        for annotator, product in zip(self.annotators, self.products):
            annotator.detach(product)
        if self.sensor is not None:
            self.sensor._invalidate_sensor()  # audited teardown, no installed source patch
        else:
            for product in self.handles:
                product.destroy()
        self.closed = True

"""Opt-in NVTX stage observer for initialized Piper/Isaac experiment only.

No synchronization, tensor inspection, render pump, or SDK byte mutation.
Install AFTER all experimental wrappers; restore BEFORE their restoration.
nsys: --capture-range=nvtx --nvtx-capture=live30_capture --capture-range-end=stop.
This measures execution; it does not validate camera/source alignment.
"""
from contextlib import contextmanager
import functools
import hashlib
import os
from pathlib import Path
import threading


class Observer:
    def __init__(self, env, logger, *, warmup=30, frames=120, ik=None):
        if warmup < 0 or frames < 1:
            raise ValueError("Invalid profiler window")
        import torch.cuda.nvtx as nvtx
        self.nvtx = nvtx
        self.changes = []
        self.owner_thread = threading.get_ident()
        self.tick = 0
        self.capture_open = False
        self.control_open = False
        self.counts = {}
        self.warmup, self.frames = warmup, frames
        try:
            self._replace(logger, "begin_step", self._begin(logger.begin_step))
            self._replace(logger, "end_step", self._end(logger.end_step))
            original_stage = logger.stage

            @contextmanager
            def stage(name):
                with self.zone("stage:" + name), original_stage(name):
                    yield

            self._replace(logger, "stage", stage)
            self.wrap(env, "_advance", "advance_and_packets")
            self.wrap(env, "capture_measured_state", "state_D2H")
            self.wrap(env, "_apply", "native_target_mapping")
            self.wrap(env.sim, "step", lambda *a, **kw: "sim_step:render=" + str(kw.get("render", True)))
            self.wrap(env.sim, "render", "sim_render")
            for index, robot in enumerate(env.robots):
                self.wrap(robot, "write_data_to_sim", f"robot{index}:write")
                self.wrap(robot, "update", f"robot{index}:update")
            self.wrap(env.camera, "update", "camera_update")
            if hasattr(env.camera, "capture_boundary"):
                self.wrap(env.camera, "capture_boundary", "camera_boundary")
            if getattr(env, "vr_runtime", None) is not None:
                self.wrap(env.vr_runtime, "update", "vr_runtime_update")
            if ik is not None:
                self.wrap(ik, "solve", "ik_solve")
        except BaseException:
            self.restore()
            raise

    @contextmanager
    def zone(self, name):
        # Python scopes may run outside the measured range. No GPU dependency added.
        self.counts[name] = self.counts.get(name, 0) + 1
        self.nvtx.range_push(name)
        try:
            yield
        finally:
            self.nvtx.range_pop()

    def _replace(self, obj, name, value):
        previous = vars(obj).get(name)
        existed = name in vars(obj)
        setattr(obj, name, value)
        self.changes.append((obj, name, existed, previous))

    def wrap(self, obj, name, label):
        original = getattr(obj, name)

        @functools.wraps(original)
        def wrapped(*args, **kwargs):
            name = label(*args, **kwargs) if callable(label) else label
            with self.zone(name):
                return original(*args, **kwargs)

        self._replace(obj, name, wrapped)

    def _begin(self, original):
        @functools.wraps(original)
        def begin(*args, **kwargs):
            if threading.get_ident() != self.owner_thread or self.control_open:
                raise RuntimeError("Profiler expected serial paired control boundaries")
            self.tick += 1
            if self.tick == self.warmup + 1:
                self.nvtx.range_push("live30_capture")
                self.capture_open = True
            if self.capture_open:
                self.nvtx.range_push(f"control:{self.tick}")
                self.control_open = True
            return original(*args, **kwargs)
        return begin

    def _end(self, original):
        @functools.wraps(original)
        def end(*args, **kwargs):
            try:
                return original(*args, **kwargs)
            finally:
                if self.control_open:
                    self.nvtx.range_pop()
                    self.control_open = False
                if self.capture_open and self.tick == self.warmup + self.frames:
                    self.nvtx.range_pop()
                    self.capture_open = False
        return end

    def receipt(self):
        return {"observer_only": True, "tensor_reads_added": False,
                "synchronization_added": False, "source_alignment_proven": False,
                "warmup": self.warmup, "frames": self.frames, "begun_ticks": self.tick,
                "method_counts": dict(self.counts), "thread_id": self.owner_thread,
                "cpu_affinity": sorted(os.sched_getaffinity(0)),
                "source_sha256": hashlib.sha256(Path(__file__).read_bytes()).hexdigest()}

    def restore(self):
        if self.control_open:
            self.nvtx.range_pop()
            self.control_open = False
        if self.capture_open:
            self.nvtx.range_pop()
            self.capture_open = False
        for obj, name, existed, previous in reversed(self.changes):
            if existed:
                setattr(obj, name, previous)
            else:
                delattr(obj, name)
        self.changes.clear()


def install(env, logger, *, warmup=30, frames=120, ik=None):
    return Observer(env, logger, warmup=warmup, frames=frames, ik=ik)

"""CPU RGBA triplets -> three existing FFmpeg NVENC processes; probe only.

No subprocess starts on import. Instantiate in an explicitly scheduled GPU probe.
submit() owns CPU copies. Sidecar describes INPUT admission, not decoded output.
"""
from pathlib import Path
import json
import queue
import subprocess
import threading
import time


class FFmpegTripleEncoder:
    ROLES = ("left_wrist", "right_wrist", "scene")

    def __init__(self, directory, width=960, height=600, fps=50, gpu=0,
                 gop=50, capacity=8, bitrate="16M", packed_rgb=True):
        self.directory = Path(directory)
        self.directory.mkdir(parents=True, exist_ok=False)
        self.width, self.height = width, height
        self.pending = queue.Queue(maxsize=capacity)
        self.error = None
        self.submitted = self.written = 0
        self.closed = False
        self.processes, self.logs = {}, []
        self.sidecar = (self.directory / "input.jsonl").open("w")
        self.config = dict(width=width, height=height, fps=fps, gpu=gpu,
                           gop=gop, capacity=capacity, bitrate=bitrate, packed_rgb=packed_rgb)
        try:
            for role in self.ROLES:
                logfile = (self.directory / f"{role}.stderr").open("wb")
                self.logs.append(logfile)
                # rgb0 consumes the same four byte RGBA layout and ignores alpha.
                # This avoids CPU RGBA -> planar YUV conversion before NVENC.
                source_format = "rgb0" if packed_rgb else "rgba"
                target_format = "rgb0" if packed_rgb else "yuv420p"
                command = ["/usr/bin/ffmpeg", "-hide_banner", "-loglevel", "warning",
                           "-nostdin", "-n", "-f", "rawvideo", "-pixel_format", source_format,
                           "-video_size", f"{width}x{height}", "-framerate", str(fps),
                           "-i", "pipe:0", "-an", "-c:v", "h264_nvenc", "-gpu", str(gpu),
                           "-preset", "p1", "-tune", "ull", "-bf", "0", "-g", str(gop),
                           "-rc-lookahead", "0", "-multipass", "disabled",
                           "-zerolatency", "1", "-delay", "0", "-rc", "vbr",
                           "-b:v", bitrate, "-pix_fmt", target_format, "-f", "h264",
                           str(self.directory / f"{role}.h264")]
                self.processes[role] = subprocess.Popen(command, stdin=subprocess.PIPE,
                    stdout=subprocess.DEVNULL, stderr=logfile, bufsize=0)
            (self.directory / "config.json").write_text(json.dumps(self.config, indent=2))
        except BaseException:
            self._terminate()
            self.sidecar.close()
            raise
        self.worker = threading.Thread(target=self._feed, name="ffmpeg-triple-feeder", daemon=True)
        self.worker.start()

    def check(self):
        if self.error is not None:
            raise RuntimeError("FFmpeg feeder failed") from self.error
        for role, proc in self.processes.items():
            if not self.closed and proc.poll() is not None:
                raise RuntimeError(f"{role} exited early: {proc.returncode}")

    def submit(self, frames, metadata):
        if self.closed:
            raise RuntimeError("encoder is closed")
        self.check()
        if set(frames) != set(self.ROLES):
            raise ValueError("exactly three declared camera roles required")
        owned = {}
        for role in self.ROLES:
            array = frames[role]
            if array.shape != (self.height, self.width, 4) or array.dtype.name != "uint8":
                raise ValueError(f"invalid RGBA8 frame for {role}")
            owned[role] = array.tobytes(order="C")
        record = json.loads(json.dumps(metadata))
        record.update(input_index=self.submitted, admit_wall_ns=time.monotonic_ns(),
                      output_alignment_proven=False)
        try:
            self.pending.put_nowait((owned, record))
        except queue.Full as exc:
            raise RuntimeError("encoding backlog exceeded bounded ring; probe failed") from exc
        self.submitted += 1

    def _feed(self):
        try:
            while True:
                item = self.pending.get()
                if item is None:
                    break
                frames, record = item
                for role in self.ROLES:
                    view = memoryview(frames[role])
                    while view:
                        count = self.processes[role].stdin.write(view)
                        if not count:
                            raise RuntimeError(f"short pipe write: {role}")
                        view = view[count:]
                record["pipes_written_wall_ns"] = time.monotonic_ns()
                self.sidecar.write(json.dumps(record, separators=(",", ":")) + "\n")
                self.written += 1
        except BaseException as exc:
            self.error = exc

    def _terminate(self):
        for proc in self.processes.values():
            if proc.poll() is None:
                proc.terminate()
                try:
                    proc.wait(timeout=5)
                except subprocess.TimeoutExpired:
                    proc.kill()
                    proc.wait()
        for log in self.logs:
            log.close()

    def finish(self, timeout=30):
        if self.closed:
            raise RuntimeError("finish called twice")
        try:
            self.check()
            self.pending.put(None, timeout=timeout)
            self.worker.join(timeout=timeout)
            if self.worker.is_alive():
                raise RuntimeError("feeder failed to drain")
            self.check()
            for proc in self.processes.values():
                proc.stdin.close()
            for role, proc in self.processes.items():
                if proc.wait(timeout=timeout) != 0:
                    raise RuntimeError(f"{role} failed to flush: {proc.returncode}")
            if self.written != self.submitted:
                raise RuntimeError("input triplets were lost")
        finally:
            self.closed = True
            self._terminate()
            self.sidecar.flush()
            self.sidecar.close()

